WITH lines AS (SELECT id, effective_from, currency, EXPLODE(discounts) AS tier_value FROM price_tiers) SELECT CASE WHEN tier_value >= 62 THEN 'LARGE' ELSE 'SMALL' END AS tier_value_tier, APPROX_PERCENTILE(tier_value, ARRAY(0.25, 0.5, 0.75)) AS tier_value_quartiles, SUM(CASE WHEN currency = 'THB' THEN tier_value ELSE 0 END) AS thb_tier_value, ROUND(SUM(tier_value) / NULLIF(COUNT(CASE WHEN currency = 'EUR' THEN 1 END), 0), 2) AS tier_value_per_eur, APPROX_PERCENTILE(tier_value, 0.9) AS tier_value_p90 FROM lines GROUP BY tier_value_tier ORDER BY thb_tier_value DESC NULLS LAST;
